import json
from pathlib import Path
import numpy as np
from PIL import Image
from scipy import ndimage as ndi
P=Path('predictions.json')
def save(i,series):
 d=json.loads(P.read_text());d[f'fig_{i:02}.png']=series;P.write_text(json.dumps(d,ensure_ascii=False,indent=2))
def s(name,points):return {'name':name,'data':[{'x':round(float(x),6),'y':round(float(y),6)} for x,y in points]}
def manual(i,series):save(i,[s(n,p) for n,p in series])
def arr(i):return np.asarray(Image.open(f'images/fig_{i:02}.png').convert('RGB')).astype(float)
def mask(i,c):
 a=arr(i);r,g,b=a[:,:,0],a[:,:,1],a[:,:,2]
 if c=='blue':return (b>r+45)&(b>g+25)
 if c=='red':return (r>g+50)&(r>b+40)
 if c=='green':return (g>r+35)&(g>b+20)
 if c=='cyan':return (g>r+35)&(b>r+35)&(abs(g-b)<80)
 if c=='purple':return (r>g+25)&(b>g+25)&(abs(r-b)<90)
 if c=='orange':return (r>150)&(g>65)&(g<200)&(b<100)&(r>g+35)
 if c=='black':return np.max(a,axis=2)<110
 if c=='steel':return (b>r+20)&(g>r+10)&(abs(g-b)<90)
 if c=='pink':return (r>150)&(b>90)&(g<r-60)&(g<b-30)
 raise ValueError(c)
def comps(i,c,box,minarea=3,maxarea=500):
 m=mask(i,c);x0,y0,x1,y1=box
 m[:int(y0),:]=False;m[int(y1)+1:,:]=False;m[:,:int(x0)]=False;m[:,int(x1)+1:]=False
 labs,num=ndi.label(m,np.ones((3,3)));out=[]
 for k,sl in enumerate(ndi.find_objects(labs),1):
  if sl is None:continue
  ys,xs=np.where(labs[sl]==k);area=len(xs)
  if minarea<=area<=maxarea:
   out.append((float(xs.mean()+sl[1].start),float(ys.mean()+sl[0].start),area))
 return sorted(out)
def scaled(coords,cal):
 x0,x1,xv0,xv1,y0,y1,yv0,yv1=cal
 return [(xv0+(x-x0)/(x1-x0)*(xv1-xv0),yv0+(y-y0)/(y1-y0)*(yv1-yv0)) for x,y,*_ in coords]
def auto(i,spec,box,cal,minarea=3):
 series=[]
 for name,c in spec:
  co=comps(i,c,box,minarea);series.append(s(name,scaled(co,cal)));print(i,name,len(co),co)
 save(i,series)
